package com.nypunya.progress.service;
import com.nypunya.progress.entity.CourseProgress; import com.nypunya.progress.repository.CourseProgressRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List; import java.util.NoSuchElementException;
@Service public class ProgressService { private final CourseProgressRepository repo; public ProgressService(CourseProgressRepository repo){this.repo=repo;}
 @Transactional public CourseProgress initialize(Long studentId,Long courseId,Integer totalItems){if(totalItems==null||totalItems<0)throw new IllegalArgumentException("totalItems must be non-negative");return repo.findByStudentIdAndCourseId(studentId,courseId).orElseGet(()->{CourseProgress p=new CourseProgress();p.setStudentId(studentId);p.setCourseId(courseId);p.setTotalItems(totalItems);p.setCompletedItems(0);return repo.save(p);});}
 @Transactional public CourseProgress update(Long studentId,Long courseId,Integer completedItems,Integer totalItems){if(completedItems==null||completedItems<0)throw new IllegalArgumentException("completedItems must be non-negative");if(totalItems==null||totalItems<0)throw new IllegalArgumentException("totalItems must be non-negative");if(completedItems>totalItems)throw new IllegalArgumentException("completedItems cannot exceed totalItems");CourseProgress p=repo.findByStudentIdAndCourseId(studentId,courseId).orElseGet(()->{CourseProgress x=new CourseProgress();x.setStudentId(studentId);x.setCourseId(courseId);return x;});p.setCompletedItems(completedItems);p.setTotalItems(totalItems);return repo.save(p);}
 @Transactional(readOnly=true) public CourseProgress get(Long studentId,Long courseId){return repo.findByStudentIdAndCourseId(studentId,courseId).orElseThrow(()->new NoSuchElementException("Progress not found"));}
 @Transactional(readOnly=true) public List<CourseProgress> list(Long studentId){return repo.findByStudentId(studentId);}
}
